INSERT INTO `blend_plan` (`id`, `plan_code`, `order_id`, `plan_name`, `total_cost`, `quality_score`, `cost_score`, `stability_score`, `overall_score`, `feasible_flag`, `constraint_summary`, `score_detail`, `risk_level`, `plan_status`, `explanation`, `rule_basis`, `case_reference`, `recommend_reason`, `final_explanation`, `risk_tip`, `optimize_suggestion`, `ai_model_name`, `ai_generate_flag`, `create_by`, `create_time`, `update_time`, `final_product_batch_no`, `trace_status`)
VALUES
	(1,'P1776588684573A',1,'低硫高热值推荐方案A',2415000.00,90.00,78.00,82.00,85.00,1,'预测灰分约14.80%，预测硫分约0.46%，预测水分约6.90%，预测发热量约5341 kcal/kg，满足订单主要硬约束。','质量分较高，低硫和发热量指标余量较好；成本分中等，因使用部分高热值低硫煤种；库存稳定性良好。','low','generated','该方案优先使用低硫贫煤和弱粘煤，并搭配长焰煤，能够兼顾低硫约束和发热量要求。','命中低硫订单优先低硫煤规则、发热量下限校验规则和库存可用性约束规则。',NULL,NULL,NULL,'低硫贫煤库存相对有限，执行前需复核可用库存。','若后续成本压力增大，可少量增加长焰煤比例，但需重新校验硫分和灰分。','本地Ollama-Qwen示例模型',1,1,'2026-04-19 16:51:24','2026-04-25 13:14:17','FP2026042501','shipped'),
	(2,'P1776588684573B',2,'成本优先候选方案B',3226000.00,78.00,88.00,86.00,83.00,1,'预测灰分和硫分满足订单上限，发热量满足普通动力煤需求，但质量余量较小。','成本分较高，库存稳定性较好；质量分中等，需关注灰分波动。','medium','generated','该方案使用库存充足且成本较低的煤种，在满足普通订单约束的前提下控制总成本。','命中低成本煤使用边界规则、灰分约束优先校验规则和库存稳定性评分规则。',NULL,NULL,NULL,'高灰低价煤参与比例不宜继续提高，否则可能导致灰分风险增加。','若订单质量要求提高，应引入低灰精选煤或弱粘煤进行质量补偿。','本地Ollama-Qwen示例模型',1,1,'2026-04-19 16:51:24','2026-04-24 20:30:34',NULL,'not_executed'),
	(3,'P1776588688045A',3,'远距离运输质量优先方案C',5320000.00,92.00,72.00,76.00,82.00,1,'预测灰分、硫分和发热量均满足质量优先订单要求，适合远距离运输质量控制场景。','质量分高，成本分偏低，库存稳定性中等。','medium','generated','该方案提高了低灰精选煤和低硫贫煤占比，适合质量要求较高的远距离运输订单。','命中远距离运输质量约束规则、低硫订单优先低硫煤规则和灰分约束优先校验规则。',NULL,NULL,NULL,'低灰精选煤价格较高且库存有限，应关注成本和供应稳定性。','可在保证灰分和硫分余量的前提下适当增加长焰煤比例以降低成本。','本地Ollama-Qwen示例模型',1,1,'2026-04-19 16:51:28','2026-04-24 20:30:34',NULL,'not_executed'),
