INSERT INTO `blend_plan_feedback` (`id`, `plan_id`, `order_id`, `actual_quantity`, `actual_ash`, `actual_sulfur`, `actual_moisture`, `actual_volatile`, `actual_calorific`, `actual_cost`, `qualified_flag`, `effectiveness_eval`, `feedback_desc`, `execute_date`, `operator_id`, `case_generated_flag`, `case_id`, `status`, `create_time`, `update_time`)
VALUES
	(1,1,1,5000.00,14.90,0.47,7.00,24.20,5330.00,2420000.00,1,'良好','测试反馈：实际指标满足订单约束，硫分和热值余量较好。','2026-05-06',2,0,NULL,1,'2026-04-24 17:31:19','2026-04-24 20:30:34'),
	(2,2,2,8000.00,22.30,0.74,9.30,30.00,4850.00,3235000.00,1,'一般','测试反馈：成本控制较好，但灰分接近上限，后续需控制高灰煤比例。','2026-05-11',2,0,NULL,1,'2026-04-24 20:30:34','2026-04-24 20:30:34'),
	(3,115,6,5000.00,10.68,0.65,6.88,32.40,6048.00,2535000.00,1,'优秀','方案执行稳定，最终产品质量余量充足，适合作为低硫高热值订单参考案例。','2026-04-26',6,1,12,1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(4,116,7,3200.00,13.18,0.61,7.25,33.10,5735.00,1712000.00,0,'一般','方案理论满足但硫分余量不足，最终硫分略超订单上限，建议提高低硫精煤比例。','2026-04-26',6,1,13,1,'2026-04-25 13:28:16','2026-04-25 13:28:16');
INSERT INTO `case_sample` (`id`, `case_code`, `case_name`, `order_desc`, `blend_desc`, `result_desc`, `quality_result`, `cost_result`, `effectiveness_eval`, `status`, `create_time`, `update_time`, `business_stage`, `related_batch_no`, `related_order_id`)
VALUES
	(1,'C001','选煤厂智能配煤系统应用案例','公开文献介绍，选煤厂可根据用户要求、产品仓产品质量和储量情况进行智能配煤决策。','系统采用比例配煤或煤质配煤思路，根据产品仓质量和储量自动给出配煤方案。','应用目标是提高配煤决策效率，改善产品质量控制水平，并降低人工经验依赖。','公开资料未披露具体煤种配比和详细质量数据',NULL,'可作为产品仓质量、库存约束与用户要求联合决策的参考案例',1,'2026-04-18 16:51:28','2026-04-24 20:30:34','blending',NULL,NULL),
	(2,'C002','炼焦配煤专家系统设计案例','公开学位论文围绕炼焦配煤业务，研究专家知识库、数学模型和配煤决策支持系统的结合。','系统通过专家知识和数学模型辅助配煤方案设计，兼顾煤质、成本和库存因素。','案例说明专家规则与模型计算结合可用于降低人工经验依赖，提高方案生成效率。','公开资料未披露完整生产批次质量结果',NULL,'可作为专家知识库与配煤模型结合的参考案例',1,'2026-04-18 16:51:28','2026-04-24 20:30:34','blending',NULL,NULL),
	(3,'C003','低硫高热值订单示范案例','需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。','在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。','该案例用于系统演示：根据低硫、高热值约束检索规则并生成解释，不代表真实企业生产批次。','预测指标需由系统根据实际配比计算',2100000.00,'用于毕设原型演示的测试案例',1,'2026-04-18 16:51:28','2026-04-24 20:30:34','blending',NULL,NULL),
	(4,'C004','库存紧张下调配比案例','需求 4000 吨，热值不低于 4600，库存整体偏紧。','通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。','执行中曾出现单仓不足，经调拨后完成。','指标达标',1580000.00,'良好',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(5,'C005','大批量 6000 吨动力煤案例','大批量订单 6000 吨，硫分不高于 1.2%。','分批发运+多仓组合发运，主配长焰煤与贫煤。','成本可控，质量稳定。','硫分 0.95%，热值 4750',2890000.00,'良好',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(6,'C006','高优先级保供案例','高优先级订单 3500 吨，库存保护规则触发。','优先调用库存充足煤种，少量引入高价高热值煤补偿。','按期交付。','热值 4920',1750000.00,'优秀',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(7,'C007','低成本路径案例','优先级一般，成本敏感。','以不粘煤为主，弱粘煤为辅，控制到厂成本。','硫分略高但在合同范围内。','成本较低',980000.00,'中等',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(8,'C008','水分敏感订单案例','水分上限 8%，夏季运输。','降低高水分煤比例，加强到场检验。','未出现拒收。','全水达标',720000.00,'良好',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(9,'C009','高热值补偿案例','热值不低于 5200，基础煤热值不足。','引入高热值煤种补偿，同步评估成本上升。','热值达标。','热值 5280',1410000.00,'优秀',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(10,'C010','低硫动力煤组合案例','低硫动力煤场景，硫分不高于 0.8%。','贫煤+弱粘煤组合，严控高硫煤进入配方。','硫分 0.55%。','低硫达标',1980000.00,'优秀',1,'2026-04-21 08:47:56','2026-04-21 08:47:56','blending',NULL,NULL),
	(11,'CF000001','反馈回流案例-P1777022317698A','订单O202604005，客户南方电力公司，需求量3500吨，灰分≤17.5%，硫分≤0.6%，热值≥5100。','大屯1/3焦煤配比20%，用量700吨；河南二1贫煤配比60%，用量2100吨；大同弱粘煤配比20%，用量700吨','实际执行量1吨，执行结果未达标','灰分1%，硫分1%，水分1%，热值1',2.00,'较差',0,'2026-04-24 17:31:30','2026-04-24 17:34:58','blending',NULL,NULL),
	(12,'C-ENH-2026042501','低硫高热值商品煤配煤成功案例','客户要求5000吨动力煤，灰分≤18%，硫分≤0.80%，发热量≥5000kcal/kg。','使用PB2026042501-CL 60% + PB2026042502-CL 40%，形成FP2026042501。','最终质检合格并完成发运，质量余量充足。','灰分10.68%，硫分0.652%，水分6.88%，发热量6048kcal/kg',2535000.00,'优秀',1,'2026-04-25 13:28:16','2026-04-25 13:28:16','feedback','FP2026042501',6),
	(13,'C-ENH-2026042502','严格低硫订单风险反馈案例','客户要求3200吨动力煤，灰分≤16%，硫分≤0.60%，发热量≥5200kcal/kg。','使用PB2026042501-CL 37.5% + PB2026042502-CL 62.5%，理论满足但硫分余量不足。','最终质检硫分0.610%，略高于订单上限，需调整低硫煤比例。','灰分13.18%，硫分0.610%，水分7.25%，发热量5735kcal/kg',1712000.00,'一般',1,'2026-04-25 13:28:16','2026-04-25 13:28:16','feedback','FP2026042502',7),
	(14,'C-ENH-2026042503','成本优先动力煤候选案例','客户要求4500吨动力煤，灰分≤22%，硫分≤1.20%，发热量≥4700kcal/kg，成本优先。','使用PB2026042503-CL 70% + PB2026042501-CL 30%。','预测满足质量要求且成本较低，尚未执行。','预测灰分18.48%，硫分0.693%，水分7.94%，发热量5112kcal/kg',2012500.00,'良好',1,'2026-04-25 13:28:16','2026-04-25 13:28:16','blending',NULL,8);
