INSERT INTO `rag_knowledge` (`id`, `knowledge_code`, `title`, `knowledge_type`, `content`, `source_table`, `source_id`, `tags`, `status`, `create_time`, `update_time`)
VALUES
	(1,'KG-RULE-001','低硫订单优先低硫煤规则','rule','当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该知识用于解释低硫订单中为什么优先使用低硫贫煤、低硫长焰煤等煤种。','rule_knowledge',1,'低硫,硫分,煤种选择,经验规则',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(2,'KG-RULE-002','高硫煤限配规则','rule','当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤，避免最终产品硫分超标。','rule_knowledge',2,'高硫煤,限配,硫分,配比约束',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(3,'KG-RULE-003','灰分约束优先校验规则','rule','配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。','rule_knowledge',3,'灰分,质量约束,方案校验',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(4,'KG-RULE-004','发热量下限校验规则','rule','配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。','rule_knowledge',4,'发热量,热值补偿,质量约束',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(5,'KG-RULE-005','高热值补偿规则','rule','当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。','rule_knowledge',5,'高热值,补偿,成本控制',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(6,'KG-RULE-006','低成本煤使用边界规则','rule','低价煤种可以用于降低方案成本，但若其灰分、硫分或水分偏高，应设置使用边界，避免因低成本导致产品质量不达标。','rule_knowledge',6,'成本,灰分,硫分,配比边界',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(7,'KG-RULE-007','库存可用性约束规则','rule','参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。','rule_knowledge',7,'库存,可用库存,可执行性',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(8,'KG-RULE-008','库存稳定性评分规则','rule','在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。','rule_knowledge',8,'库存稳定性,评分排序,风险控制',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(9,'KG-RULE-009','水分控制规则','rule','配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。','rule_knowledge',9,'水分,质量约束,煤质指标',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(10,'KG-RULE-010','挥发分参考规则','rule','挥发分可作为煤化程度和燃烧特性的参考指标。对于设置挥发分参考值的订单，方案解释中应说明预测挥发分与目标值的接近程度。','rule_knowledge',10,'挥发分,煤化程度,质量解释',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(11,'KG-RULE-011','远距离运输质量约束规则','rule','对于远距离运输或重点区域供应场景，应更加关注灰分和硫分等质量指标，避免低质煤进入高要求使用场景。','rule_knowledge',11,'远距离运输,灰分,硫分,商品煤质量',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(12,'KG-RULE-012','分质堆存与分质配煤规则','rule','煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。','rule_knowledge',12,'分质堆存,煤质检测,库存管理',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(13,'KG-RULE-013','相似案例参考规则','rule','当存在与当前订单在硫分、灰分、发热量或需求量方面相近的历史案例时，可将其作为方案解释和候选方案生成的参考。','rule_knowledge',13,'相似案例,案例推理,方案解释',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(14,'KG-RULE-014','规则与算法协同规则','rule','配煤比例不宜完全由大模型直接生成，应由规则筛选、质量计算和评分排序形成候选方案，再由大模型结合知识库生成解释。','rule_knowledge',14,'大模型,规则约束,配煤算法,RAG',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(15,'KG-CASE-001','选煤厂智能配煤系统应用案例','case','公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。','case_sample',1,'智能配煤,选煤厂,产品仓,库存,质量控制',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(16,'KG-CASE-002','炼焦配煤专家系统设计案例','case','公开学位论文围绕炼焦配煤业务，研究专家知识库、数学模型和配煤决策支持系统结合。该案例适合用于说明专家知识库和数学模型协同支撑配煤决策。','case_sample',2,'炼焦配煤,专家系统,知识库,数学模型',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(17,'KG-CASE-003','低硫高热值订单示范案例','case','测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。','case_sample',3,'低硫,高热值,订单案例,方案解释',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(18,'KG-TERM-001','灰分','term','灰分是煤完全燃烧后残留的无机矿物质含量，是评价煤炭质量的重要指标。灰分偏高通常会降低煤炭利用价值，并可能影响燃烧或后续加工效果。',NULL,NULL,'灰分,Ad,煤质指标,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(19,'KG-TERM-002','硫分','term','硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。',NULL,NULL,'硫分,St,d,环保约束,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(20,'KG-TERM-003','水分','term','水分是煤中含水量指标。水分过高会影响运输、储存和有效发热量，因此配煤方案需要关注预测水分是否超过订单要求。',NULL,NULL,'水分,Mt,煤质指标,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(21,'KG-TERM-004','挥发分','term','挥发分是煤在隔绝空气条件下加热时析出的挥发性物质比例，可反映煤化程度和燃烧特性。',NULL,NULL,'挥发分,Vdaf,煤化程度,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(22,'KG-TERM-005','发热量','term','发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。',NULL,NULL,'发热量,Qnet,动力煤,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(23,'KG-TERM-006','固定碳','term','固定碳是煤在扣除水分、灰分和挥发分后剩余的可燃固体成分，是煤工业分析中的重要指标之一。',NULL,NULL,'固定碳,工业分析,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(24,'KG-TERM-007','配煤方案可行性','term','配煤方案可行性通常指方案是否同时满足订单质量约束、库存约束和业务规则约束。不可行方案不应作为最终推荐方案。',NULL,NULL,'可行性,硬约束,方案生成,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(25,'KG-TERM-008','RAG检索增强生成','term','RAG 是检索增强生成方法。在本系统中，RAG 用于从规则、案例和术语知识中检索相关内容，再交给大模型生成方案解释和风险提示。',NULL,NULL,'RAG,大模型,知识检索,术语',1,'2026-04-24 20:31:28','2026-04-24 20:31:28'),
	(26,'K-ENH-RULE-001','低硫订单优先低硫煤规则','rule','当订单硫分上限较低时，应优先选择硫分较低且煤质稳定的产品批次参与配煤；若硫分预测值接近订单上限，应给出风险提示并建议增加低硫煤比例。','rule_knowledge',1,'低硫,配煤规则,硫分,风险控制',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(27,'K-ENH-RULE-002','库存可用性与锁定规则','rule','参与配煤的产品批次必须存在可用库存，方案使用量不得超过可用库存。方案被选择或执行后，应在库存中体现锁定量或扣减量。','rule_knowledge',7,'库存,锁定量,可执行性,产品批次',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(28,'K-ENH-CASE-001','低硫高热值商品煤成功案例','case','订单O2026042501要求5000吨低硫高热值动力煤，方案P2026042501-A采用PB2026042501-CL 60%与PB2026042502-CL 40%，最终产品FP2026042501质检合格并发运。','case_sample',12,'成功案例,低硫,高热值,发运',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(29,'K-ENH-CASE-002','严格低硫订单风险反馈案例','case','订单O2026042502硫分上限0.60%，方案P2026042502-RISK理论预测接近上限，最终产品FP2026042502实测硫分0.610%，说明严格低硫订单需要保留更大质量余量。','case_sample',13,'风险案例,硫分超标,反馈,质量余量',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(30,'K-ENH-TERM-001','批次血缘追溯说明','term','批次血缘用于记录父批次到子批次的业务关系，例如原煤批次进入洗选批次、洗选批次产出产品批次、产品批次混配生成最终产品、最终产品发运形成发运批次。',NULL,NULL,'批次血缘,追溯,数据链条',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(31,'K-ENH-PROCESS-001','煤矿智能配煤全链路流程说明','doc','系统业务链路包括矿区煤种煤质、原煤生产、原煤入仓、洗选加工、洗后产品、产品库存、订单驱动配煤、最终产品质检、发运交付和执行反馈。该链路用于支撑方案解释和质量追溯。',NULL,NULL,'全链路,原煤生产,洗选加工,最终产品',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(32,'K-ENH-QUALITY-001','多阶段煤质数据说明','doc','煤质数据应按采样阶段区分，包括geological地质煤质、raw_coal原煤煤质、wash_feed入洗煤质、clean_coal洗后产品煤质、mixed_product混配产品煤质和final_product最终商品煤煤质。',NULL,NULL,'煤质,采样阶段,质量档案',1,'2026-04-25 13:28:16','2026-04-25 13:28:16'),
	(33,'K-ENH-STANDARD-001','商品煤质量与分质管理说明','doc','商品煤生产、加工、储运、销售等环节均应重视质量管理。不同质量商品煤应分质堆存、分质装车，并建立商品煤质量档案。',NULL,NULL,'商品煤质量,分质堆存,分质装车,质量档案',1,'2026-04-25 13:28:16','2026-04-25 13:28:16');
INSERT INTO `rag_retrieval_log` (`id`, `biz_type`, `biz_id`, `query_text`, `keywords`, `retrieved_ids`, `model_name`, `prompt_text`, `model_output`, `create_time`)
VALUES
	(1,'blend_generate',91,'低硫 硫分约束 高硫煤限配 高热值 热值补偿 动力煤 低灰 灰分控制 水分控制 配煤方案 质量约束 成本控制 历史案例','低硫,硫分约束,高硫煤限配,高热值,热值补偿,动力煤,低灰,灰分控制,水分控制,配煤方案,质量约束,成本控制,历史案例','17,5,4,9,1,3,22,2,11,13,15,19,20,24','deepseek-v4-pro(兜底)','你是煤矿智能配煤领域专家，请根据以下订单信息、推荐方案、命中规则、参考案例和库存信息，生成专业解释。\n\n【订单信息】\n订单编号：O202604005\n客户名称：钢铁企业自备电厂\n需求量：6000 吨\n灰分要求：≤17%\n硫分要求：≤0.7%\n水分要求：≤8.5%\n发热量要求：≥5100 kcal/kg\n优先级：2\n交付日期：2026-05-18\n（约束快照）{demandQuantity=6000.00, maxAsh=17.00, maxSulfur=0.70, maxMoisture=8.50, referenceVolatile=26.00, minCalorific=5100.00, priorityLevel=2, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=97}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：2616000.00 元\n质量评分：100\n成本评分：88\n稳定性评分：74\n综合评分：89.8\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比80.00%，使用量4800吨，预测硫分0.45%，预测热值5220，单价420元/吨\n河南二1贫煤：配比20.00%，使用量1200吨，预测硫分0.45%，预测热值5220，单价500元/吨\n\n【命中规则】\n规则1：低硫订单优先低硫煤规则（经验规则）；命中原因：因订单目标硫分不高于 0.8%，需执行高硫煤限配策略。——当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。\n规则2：高硫煤限配规则（配比约束）；命中原因：因目标热值不低于 5000 kcal/kg 且硫分要求较严，优先参考低硫煤组合经验。——当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。\n规则3：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨，需关注库存保护规则对可执行性的影响。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则4：发热量下限校验规则（质量约束）；命中原因：因订单目标热值不低于 5000 kcal/kg，建议参考高热值补偿类配煤策略。——配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n规则5：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则6：高热值补偿规则（经验规则）；命中原因：因订单灰分上限低于 18%，需严控高灰煤种作为主配比例。——当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n规则7：水分控制规则（质量约束）；命中原因：订单水分上限较严，需关注高水分煤种配比与堆放周期。——配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n规则8：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n规则9：分质堆存与分质配煤规则（经验规则）；命中原因：本单需求量大，应校核多仓合计可用量与物流执行能力。——煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。\n\n【参考案例】\n案例1：低硫高热值订单示范案例；匹配原因：低硫场景关键词命中；高热值场景关键词命中；大批量需求关键词命中——需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。 在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。\n案例2：大批量 6000 吨动力煤案例；匹配原因：低硫场景关键词命中；大批量需求关键词命中——大批量订单 6000 吨，硫分不高于 1.2%。 分批发运+多仓组合发运，主配长焰煤与贫煤。\n案例3：库存紧张下调配比案例；匹配原因：高热值场景关键词命中；库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 高热值补偿规则（rule，命中订单关键词：高热值、热值补偿、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n2. 发热量下限校验规则（rule，命中订单关键词：高热值、热值补偿、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n3. 水分控制规则（rule，命中订单关键词：水分控制、配煤方案、质量约束）\n配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n\n\n【历史案例】\n1. 低硫高热值订单示范案例（case，命中订单关键词：低硫、高硫煤限配、高热值）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n2. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n\n\n【术语说明】\n1. 发热量（term，命中订单关键词：动力煤）\n发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。\n2. 硫分（term，命中订单关键词：低硫）\n硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n河南二1贫煤可用库存：3600.00 吨，库存正常（仓库W005）\n当前推荐方案涉及煤种中存在单库可用量低于本单总需求量的情况，执行前建议确认调拨或多仓合计。\n\n请按如下格式输出（必须保留序号与小标题，便于系统解析）：\n1. 方案说明：\n2. 规则依据：\n3. 风险提示：\n4. 优化建议：\n\n要求：\n- 使用正式、简洁、专业的中文；可使用 Markdown（如 **加粗**、列表），不要使用 HTML 标签；\n- 内容必须围绕当前订单与推荐方案，结合命中规则、参考案例和 RAG 知识库检索结果；\n- 「规则依据」须明确写出与命中规则或 RAG 规则知识的对应关系，不要空泛；\n- 「风险提示」须结合库存、成本与质量约束；\n- 「优化建议」须可执行、可落地。\n','HTTP: 404 Not Found: [no body]','2026-04-24 20:53:52'),
	(2,'blend_generate',87,'硫分控制 发热量 灰分约束 配煤方案 质量约束 成本控制 历史案例','硫分控制,发热量,灰分约束,配煤方案,质量约束,成本控制,历史案例','4,3,5,9,13,20,11,15,17,24','qwen3:4b(兜底)','你是煤矿智能配煤领域专家，请根据以下订单信息、推荐方案、命中规则、参考案例和库存信息，生成专业解释。\n\n【订单信息】\n订单编号：O202604004\n客户名称：地方工业锅炉用户\n需求量：3000 吨\n灰分要求：≤24%\n硫分要求：≤1.2%\n水分要求：≤11%\n发热量要求：≥4500 kcal/kg\n优先级：1\n交付日期：2026-05-08\n（约束快照）{demandQuantity=3000.00, maxAsh=24.00, maxSulfur=1.20, maxMoisture=11.00, referenceVolatile=30.00, minCalorific=4500.00, priorityLevel=1, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=216}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：1266000.00 元\n质量评分：100\n成本评分：85.23\n稳定性评分：87\n综合评分：93.15\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比20.00%，使用量600吨，预测硫分0.6%，预测热值5036，单价420元/吨\n内蒙古鄂尔多斯不粘煤：配比60.00%，使用量1800吨，预测硫分0.6%，预测热值5036，单价390元/吨\n大同弱粘煤：配比20.00%，使用量600吨，预测硫分0.6%，预测热值5036，单价520元/吨\n\n【命中规则】\n规则1：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨；当前为高优先级订单，允许在库存保护前提下参与配煤。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则2：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则3：远距离运输质量约束规则（质量约束）；命中原因：订单硫分要求为常规水平，宜在成本与硫分达标风险之间综合权衡。——对于远距离运输或重点区域供应场景，应更加关注灰分和硫分等质量指标，避免低质煤进入高要求使用场景。\n规则4：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n\n【参考案例】\n案例1：库存紧张下调配比案例；匹配原因：库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n案例2：低硫动力煤组合案例；匹配原因：与当前订单约束关键词部分匹配——低硫动力煤场景，硫分不高于 0.8%。 贫煤+弱粘煤组合，严控高硫煤进入配方。\n案例3：高热值补偿案例；匹配原因：与当前订单约束关键词部分匹配——热值不低于 5200，基础煤热值不足。 引入高热值煤种补偿，同步评估成本上升。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 发热量下限校验规则（rule，命中订单关键词：发热量、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n2. 灰分约束优先校验规则（rule，命中订单关键词：灰分约束、配煤方案、质量约束）\n配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n3. 高热值补偿规则（rule，命中订单关键词：发热量、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n\n\n【历史案例】\n1. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n2. 低硫高热值订单示范案例（case，命中订单关键词：发热量）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n\n\n【术语说明】\n1. 水分（term，命中订单关键词：发热量、配煤方案）\n水分是煤中含水量指标。水分过高会影响运输、储存和有效发热量，因此配煤方案需要关注预测水分是否超过订单要求。\n2. 配煤方案可行性（term，命中订单关键词：质量约束）\n配煤方案可行性通常指方案是否同时满足订单质量约束、库存约束和业务规则约束。不可行方案不应作为最终推荐方案。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n内蒙古鄂尔多斯不粘煤可用库存：12000.00 吨，库存充足（仓库W002）\n大同弱粘煤可用库存：4200.00 吨，库存正常（仓库W004）\n当前推荐方案涉及煤种库存整体可支撑本次执行，无明显库存不足风险。\n\n请按如下格式输出（必须保留序号与小标题，便于系统解析）：\n1. 方案说明：\n2. 规则依据：\n3. 风险提示：\n4. 优化建议：\n\n要求：\n- 使用正式、简洁、专业的中文；可使用 Markdown（如 **加粗**、列表），不要使用 HTML 标签；\n- 内容必须围绕当前订单与推荐方案，结合命中规则、参考案例和 RAG 知识库检索结果；\n- 「规则依据」须明确写出与命中规则或 RAG 规则知识的对应关系，不要空泛；\n- 「风险提示」须结合库存、成本与质量约束；\n- 「优化建议」须可执行、可落地。\n','IllegalStateException','2026-04-24 20:56:26'),
	(3,'blend_generate',95,'低硫 硫分约束 高硫煤限配 高热值 热值补偿 动力煤 低灰 灰分控制 水分控制 配煤方案 质量约束 成本控制 历史案例','低硫,硫分约束,高硫煤限配,高热值,热值补偿,动力煤,低灰,灰分控制,水分控制,配煤方案,质量约束,成本控制,历史案例','17,5,4,9,1,3,22,2,11,13,15,19,20,24','deepseek-v4-pro','你是煤矿智能配煤领域专家，请根据以下订单信息、推荐方案、命中规则、参考案例和库存信息，生成专业解释。\n\n【订单信息】\n订单编号：O202604005\n客户名称：钢铁企业自备电厂\n需求量：6000 吨\n灰分要求：≤17%\n硫分要求：≤0.7%\n水分要求：≤8.5%\n发热量要求：≥5100 kcal/kg\n优先级：2\n交付日期：2026-05-18\n（约束快照）{demandQuantity=6000.00, maxAsh=17.00, maxSulfur=0.70, maxMoisture=8.50, referenceVolatile=26.00, minCalorific=5100.00, priorityLevel=2, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=97}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：2616000.00 元\n质量评分：100\n成本评分：88\n稳定性评分：74\n综合评分：89.8\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比80.00%，使用量4800吨，预测硫分0.45%，预测热值5220，单价420元/吨\n河南二1贫煤：配比20.00%，使用量1200吨，预测硫分0.45%，预测热值5220，单价500元/吨\n\n【命中规则】\n规则1：低硫订单优先低硫煤规则（经验规则）；命中原因：因订单目标硫分不高于 0.8%，需执行高硫煤限配策略。——当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。\n规则2：高硫煤限配规则（配比约束）；命中原因：因目标热值不低于 5000 kcal/kg 且硫分要求较严，优先参考低硫煤组合经验。——当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。\n规则3：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨，需关注库存保护规则对可执行性的影响。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则4：发热量下限校验规则（质量约束）；命中原因：因订单目标热值不低于 5000 kcal/kg，建议参考高热值补偿类配煤策略。——配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n规则5：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则6：高热值补偿规则（经验规则）；命中原因：因订单灰分上限低于 18%，需严控高灰煤种作为主配比例。——当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n规则7：水分控制规则（质量约束）；命中原因：订单水分上限较严，需关注高水分煤种配比与堆放周期。——配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n规则8：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n规则9：分质堆存与分质配煤规则（经验规则）；命中原因：本单需求量大，应校核多仓合计可用量与物流执行能力。——煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。\n\n【参考案例】\n案例1：低硫高热值订单示范案例；匹配原因：低硫场景关键词命中；高热值场景关键词命中；大批量需求关键词命中——需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。 在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。\n案例2：大批量 6000 吨动力煤案例；匹配原因：低硫场景关键词命中；大批量需求关键词命中——大批量订单 6000 吨，硫分不高于 1.2%。 分批发运+多仓组合发运，主配长焰煤与贫煤。\n案例3：库存紧张下调配比案例；匹配原因：高热值场景关键词命中；库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 高热值补偿规则（rule，命中订单关键词：高热值、热值补偿、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n2. 发热量下限校验规则（rule，命中订单关键词：高热值、热值补偿、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n3. 水分控制规则（rule，命中订单关键词：水分控制、配煤方案、质量约束）\n配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n\n\n【历史案例】\n1. 低硫高热值订单示范案例（case，命中订单关键词：低硫、高硫煤限配、高热值）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n2. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n\n\n【术语说明】\n1. 发热量（term，命中订单关键词：动力煤）\n发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。\n2. 硫分（term，命中订单关键词：低硫）\n硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n河南二1贫煤可用库存：3600.00 吨，库存正常（仓库W005）\n当前推荐方案涉及煤种中存在单库可用量低于本单总需求量的情况，执行前建议确认调拨或多仓合计。\n\n请按如下格式输出（必须保留序号与小标题，便于系统解析）：\n1. 方案说明：\n2. 规则依据：\n3. 风险提示：\n4. 优化建议：\n\n要求：\n- 使用正式、简洁、专业的中文；可使用 Markdown（如 **加粗**、列表），不要使用 HTML 标签；\n- 内容必须围绕当前订单与推荐方案，结合命中规则、参考案例和 RAG 知识库检索结果；\n- 「规则依据」须明确写出与命中规则或 RAG 规则知识的对应关系，不要空泛；\n- 「风险提示」须结合库存、成本与质量约束；\n- 「优化建议」须可执行、可落地。\n','### 1. 方案说明\n推荐方案‑A 针对钢铁企业自备电厂 O202604005 号订单（需求 6000 吨，灰分≤17%、硫分≤0.7%、水分≤8.5%、发热量≥5100 kcal/kg），采用 **山西朔州长焰煤 80%（4800 吨） + 河南二1贫煤 20%（1200 吨）** 进行配煤。  \n预测成品硫分 0.45%，热值 5220 kcal/kg，经系统全面校验，灰分、水分等指标均满足订单上限要求，**质量评分满分 100**。总成本 2,616,000 元，成本评分 88，综合评分 89.8，整体方案经济性与质量达标性兼顾良好。\n\n### 2. 规则依据\n方案生成与评价过程严格遵循了以下命中规则及知识库规则，确保合规与最优：\n\n- **低硫优先与高硫煤限配**（命中规则 1、2，RAG 规则“低硫订单优先低硫煤规则”）：  \n  订单硫分上限 0.7%（≤0.8%），方案所选煤种预测硫分均为 0.45%，未引入高硫煤种，完全符合低硫优先及高硫限配策略，避免成品硫分超标。\n\n- **发热量下限校验与高热值补偿**（命中规则 4、6，RAG 规则“发热量下限校验规则”“高热值补偿规则”）：  \n  目标热值 ≥5100 kcal/kg，方案预测热值 5220 kcal/kg。通过引入河南二1贫煤（高热值煤种）对长焰煤进行热值补偿，同时控制高价贫煤占比仅 20%，在满足热值下限的前提下尽量控制成本。\n\n- **灰分、水分质量约束校验**（命中规则 3、7，RAG 规则“水分控制规则”）：  \n  方案生成后已进行灰分、水分预测校验，全部符合灰分≤17%、水分≤8.5% 的要求，故质量评分满分。水分控制规则生效，避免了高水分煤种潜在风险。\n\n- **库存可用性与稳定性约束**（命中规则 5、8）：  \n  长焰煤可用库存 10000 吨，贫煤可用库存 3600 吨，方案用量均不超库存。贫煤单库库存（3600 吨）低于订单总量 6000 吨，稳定性评分为 74，提示分仓调拨风险，符合“库存稳定性评分规则”。\n\n- **分质堆存与分质配煤**（命中规则 9）：  \n  长焰煤（W001 仓）与贫煤（W005 仓）分质存放，配煤时依据煤质检测结果选择，实现按质调用，便于煤质稳定控制。\n\n- **参考案例与知识库佐证**：  \n  低硫高热值订单示范案例（案例 1）和 6000 吨大批量动力煤案例（案例 2）同样推荐“长焰煤+贫煤”组合，并强调低硫、高热值场景下高硫煤限配及多仓组合发运，与本方案策略一致。\n\n### 3. 风险提示\n- **库存结构性风险**：河南二1贫煤单库可用量仅 3600 吨，虽满足本次 1200 吨需求，但若生产波动需提升贫煤比例，或后续有同煤种订单，将面临单库不足问题，需依赖快速调拨或增量采购，存在供应中断隐患。\n- **成本波动敏感性**：贫煤单价 500 元/吨，为长焰煤的 1.19 倍，配比每提升 1%，总成本升高约 4800 元。若煤质波动导致热值不足，需被迫增加贫煤用量，将显著推高成本。\n- **质量约束余量**：成品硫分 0.45% 距上限 0.7% 较充裕，但灰分、水分未给出具体预测值，若长焰煤到场灰分接近临界或水分偏高，可能挤压合格余量，需关注到厂煤质一致性。\n- **大批量执行稳定性**：单次交付 6000 吨，若贫煤所在 W005 仓出库效率或物流衔接不畅，可能影响分批发运节奏与交付日期，系统稳定性评分 74 已反映该风险。\n\n### 4. 优化建议\n- **提前锁定贫煤库存并建立备用煤源**：针对河南二1贫煤库存偏紧情况，建议立即与供应商确认 W005 仓可用量，并提前办理分仓调拨手续（如从其他筒仓调入），或将低硫高热值的弱粘煤作为应急替代煤种纳入备选池。\n- **优化配比降本增稳**：若交货期允许，可小幅提高长焰煤比例至 82%–83%，相应降低贫煤用量，在满足热值下限（≥5100 kcal/kg）的条件下，可降低成本并减少对单库受限煤种的依赖。需小样实验验证热值补偿效果。\n- **执行分批发运与多仓组合**：参考案例 2“大批量 6000 吨动力煤分批发运+多仓组合”经验，制定分批次发运计划，利用长焰煤的大库存优势，以 2–3 批搭配贫煤出库，规避单仓出库瓶颈。\n- **强化到厂煤质预检**：在装车/进仓前对长焰煤灰分、水分加密检测，一旦发现接近阈值，及时启用备选煤种微调配方，确保成品合格率。\n- **动态监测库存与价格**：将贫煤库存预警线设为 2000 吨，触发后自动启用替代方案，同时关注替代煤种市场价格变化，为快速切换提供数据支撑。','2026-04-24 20:57:07'),
	(4,'blend_generate',99,'低硫 硫分约束 高硫煤限配 高热值 热值补偿 动力煤 低灰 灰分控制 水分控制 配煤方案 质量约束 成本控制 历史案例','低硫,硫分约束,高硫煤限配,高热值,热值补偿,动力煤,低灰,灰分控制,水分控制,配煤方案,质量约束,成本控制,历史案例','17,5,4,9,1,3,22,2,11,13,15,19,20,24','deepseek-v4-pro','你是煤矿智能配煤系统中的方案解释助手。\n你的任务是根据订单信息、推荐方案、命中的规则知识、历史案例和 RAG 知识库内容，生成可解释的方案说明。\n\n请严格遵守以下要求：\n1. 只能依据给定的订单、方案和知识库内容进行解释；\n2. 不要编造未提供的煤种、规则、案例或检测数据；\n3. 不要直接修改配煤比例；\n4. 如果知识不足，请在对应字段中说明“当前知识库依据不足”；\n5. 输出内容应面向煤矿业务人员，语言清晰、简洁、专业。\n\n【订单信息】\n订单编号：O202604005\n客户名称：钢铁企业自备电厂\n需求量：6000 吨\n灰分要求：≤17%\n硫分要求：≤0.7%\n水分要求：≤8.5%\n发热量要求：≥5100 kcal/kg\n优先级：2\n交付日期：2026-05-18\n（约束快照）{demandQuantity=6000.00, maxAsh=17.00, maxSulfur=0.70, maxMoisture=8.50, referenceVolatile=26.00, minCalorific=5100.00, priorityLevel=2, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=97}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：2616000.00 元\n质量评分：100\n成本评分：88\n稳定性评分：74\n综合评分：89.8\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比80.00%，使用量4800吨，预测硫分0.45%，预测热值5220，单价420元/吨\n河南二1贫煤：配比20.00%，使用量1200吨，预测硫分0.45%，预测热值5220，单价500元/吨\n\n【命中规则】\n规则1：低硫订单优先低硫煤规则（经验规则）；命中原因：因订单目标硫分不高于 0.8%，需执行高硫煤限配策略。——当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。\n规则2：高硫煤限配规则（配比约束）；命中原因：因目标热值不低于 5000 kcal/kg 且硫分要求较严，优先参考低硫煤组合经验。——当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。\n规则3：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨，需关注库存保护规则对可执行性的影响。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则4：发热量下限校验规则（质量约束）；命中原因：因订单目标热值不低于 5000 kcal/kg，建议参考高热值补偿类配煤策略。——配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n规则5：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则6：高热值补偿规则（经验规则）；命中原因：因订单灰分上限低于 18%，需严控高灰煤种作为主配比例。——当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n规则7：水分控制规则（质量约束）；命中原因：订单水分上限较严，需关注高水分煤种配比与堆放周期。——配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n规则8：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n规则9：分质堆存与分质配煤规则（经验规则）；命中原因：本单需求量大，应校核多仓合计可用量与物流执行能力。——煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。\n\n【参考案例】\n案例1：低硫高热值订单示范案例；匹配原因：低硫场景关键词命中；高热值场景关键词命中；大批量需求关键词命中——需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。 在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。\n案例2：大批量 6000 吨动力煤案例；匹配原因：低硫场景关键词命中；大批量需求关键词命中——大批量订单 6000 吨，硫分不高于 1.2%。 分批发运+多仓组合发运，主配长焰煤与贫煤。\n案例3：库存紧张下调配比案例；匹配原因：高热值场景关键词命中；库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 高热值补偿规则（rule，命中订单关键词：高热值、热值补偿、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n2. 发热量下限校验规则（rule，命中订单关键词：高热值、热值补偿、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n3. 水分控制规则（rule，命中订单关键词：水分控制、配煤方案、质量约束）\n配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n\n\n【历史案例】\n1. 低硫高热值订单示范案例（case，命中订单关键词：低硫、高硫煤限配、高热值）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n2. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n\n\n【术语说明】\n1. 发热量（term，命中订单关键词：动力煤）\n发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。\n2. 硫分（term，命中订单关键词：低硫）\n硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n河南二1贫煤可用库存：3600.00 吨，库存正常（仓库W005）\n当前推荐方案涉及煤种中存在单库可用量低于本单总需求量的情况，执行前建议确认调拨或多仓合计。\n\n请严格输出 JSON，不要输出 Markdown，不要添加多余解释。JSON 必须只包含以下字段：\n{\n  \"ruleBasis\": \"说明命中的规则依据，以及这些规则如何约束当前方案\",\n  \"caseReference\": \"说明可参考的历史案例；如果案例不足，写当前知识库依据不足\",\n  \"recommendReason\": \"说明推荐该方案的原因，结合质量、成本、库存和评分\",\n  \"riskTip\": \"说明质量、库存、成本或执行风险\",\n  \"finalExplanation\": \"面向业务人员的最终综合解释\"\n}\n','{\n  \"ruleBasis\": \"本方案命中9条规则，核心包括：低硫订单优先低硫煤规则与高硫煤限配规则，要求硫分上限≤0.7%时优先选用低硫煤种并限制高硫煤参与，山西朔州长焰煤（硫分0.45%）与河南二1贫煤（硫分0.45%）均为低硫煤种，符合约束；发热量下限校验规则与高热值补偿规则，要求预测热值≥5100 kcal/kg，方案预测热值5220 kcal/kg，通过引入热值较高的贫煤补偿长焰煤实现达标；灰分约束优先校验规则与水分控制规则作为质量约束，方案确保预测灰分≤17%、水分≤8.5%；库存可用性约束规则确认两煤种可用库存满足配比用量，库存稳定性评分规则提示单库可用量低于总需求量风险，分质堆存与分质配煤规则指导多仓协同调用。\",\n  \"caseReference\": \"案例1（低硫高热值订单示范案例）匹配低硫、高热值、大批量需求，优先选择低硫贫煤与长焰煤组合，与本方案煤种选择一致；案例2（大批量6000吨动力煤案例）匹配低硫、大批量需求，主配长焰煤与贫煤，支持多仓组合发运，与本方案规模与煤种策略相符；案例3（库存紧张下调配比案例）提供库存协调思路，当前贫煤库存3600吨略低于总需求量6000吨，可借鉴其通过调整周转快慢煤种占比保障交付的经验。\",\n  \"recommendReason\": \"方案综合评分89.8分，质量评分100分，硫分、灰分、水分、热值均满足订单要求；成本评分88分，总成本261.6万元，单价436元/吨，在可用煤种中成本表现良好；采用长焰煤（单价420元/吨）为主、贫煤（单价500元/吨）为辅，比例8:2，既利用低成本煤种，又通过少量高热值煤种补偿热值，兼顾质量与成本。山西朔州长焰煤库存10000吨充足，河南二1贫煤库存3600吨可满足1200吨用量，但需注意单库低于总量的调拨风险。\",\n  \"riskTip\": \"河南二1贫煤单库可用量3600吨，低于本单总需求量6000吨，执行前建议确认调拨或多仓合计以保障供应连续性；贫煤占比20%属较高价煤种，若库存周转偏慢需关注成本稳定；交付期2026年5月18日前需校验水分堆放周期，避免长焰煤水分波动影响质量；方案为预测值，实际配煤需依据入仓检测数据微调。\",\n  \"finalExplanation\": \"针对钢铁企业自备电厂6000吨动力煤订单（灰分≤17%、硫分≤0.7%、水分≤8.5%、发热量≥5100 kcal/kg），推荐方案-A采用山西朔州长焰煤4800吨（80%）与河南二1贫煤1200吨（20%）组合，预测硫分0.45%、热值5220 kcal/kg，全部质量指标达标，总成本约261.6万元。该方案基于低硫煤优先、高热值补偿等规则生成，符合历史低硫高热值大批量订单案例经验，综合评分89.8分（质量100分、成本88分、稳定性74分）。库存方面，长焰煤库存充足，贫煤库存3600吨尚可满足本单用量，但单库量低于总需求，建议提前落实调拨或启用多仓组合，确保按时交付。执行时请关注煤质实测水分和堆放周期，以稳定最终产品质量。\"\n}','2026-04-24 21:09:14'),
	(5,'blend_generate',103,'硫分控制 发热量 灰分约束 配煤方案 质量约束 成本控制 历史案例','硫分控制,发热量,灰分约束,配煤方案,质量约束,成本控制,历史案例','4,3,5,9,13,20,11,15,17,24','deepseek-v4-pro','你是煤矿智能配煤系统中的方案解释助手。\n你的任务是根据订单信息、推荐方案、命中的规则知识、历史案例和 RAG 知识库内容，生成可解释的方案说明。\n\n请严格遵守以下要求：\n1. 只能依据给定的订单、方案和知识库内容进行解释；\n2. 不要编造未提供的煤种、规则、案例或检测数据；\n3. 不要直接修改配煤比例；\n4. 如果知识不足，请在对应字段中说明“当前知识库依据不足”；\n5. 输出内容应面向煤矿业务人员，语言清晰、简洁、专业。\n\n【订单信息】\n订单编号：O202604004\n客户名称：地方工业锅炉用户\n需求量：3000 吨\n灰分要求：≤24%\n硫分要求：≤1.2%\n水分要求：≤11%\n发热量要求：≥4500 kcal/kg\n优先级：1\n交付日期：2026-05-08\n（约束快照）{demandQuantity=3000.00, maxAsh=24.00, maxSulfur=1.20, maxMoisture=11.00, referenceVolatile=30.00, minCalorific=4500.00, priorityLevel=1, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=216}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：1266000.00 元\n质量评分：100\n成本评分：85.23\n稳定性评分：87\n综合评分：93.15\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比20.00%，使用量600吨，预测硫分0.6%，预测热值5036，单价420元/吨\n内蒙古鄂尔多斯不粘煤：配比60.00%，使用量1800吨，预测硫分0.6%，预测热值5036，单价390元/吨\n大同弱粘煤：配比20.00%，使用量600吨，预测硫分0.6%，预测热值5036，单价520元/吨\n\n【命中规则】\n规则1：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨；当前为高优先级订单，允许在库存保护前提下参与配煤。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则2：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则3：远距离运输质量约束规则（质量约束）；命中原因：订单硫分要求为常规水平，宜在成本与硫分达标风险之间综合权衡。——对于远距离运输或重点区域供应场景，应更加关注灰分和硫分等质量指标，避免低质煤进入高要求使用场景。\n规则4：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n\n【参考案例】\n案例1：库存紧张下调配比案例；匹配原因：库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n案例2：低硫动力煤组合案例；匹配原因：与当前订单约束关键词部分匹配——低硫动力煤场景，硫分不高于 0.8%。 贫煤+弱粘煤组合，严控高硫煤进入配方。\n案例3：高热值补偿案例；匹配原因：与当前订单约束关键词部分匹配——热值不低于 5200，基础煤热值不足。 引入高热值煤种补偿，同步评估成本上升。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 发热量下限校验规则（rule，命中订单关键词：发热量、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n2. 灰分约束优先校验规则（rule，命中订单关键词：灰分约束、配煤方案、质量约束）\n配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n3. 高热值补偿规则（rule，命中订单关键词：发热量、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n\n\n【历史案例】\n1. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n2. 低硫高热值订单示范案例（case，命中订单关键词：发热量）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n\n\n【术语说明】\n1. 水分（term，命中订单关键词：发热量、配煤方案）\n水分是煤中含水量指标。水分过高会影响运输、储存和有效发热量，因此配煤方案需要关注预测水分是否超过订单要求。\n2. 配煤方案可行性（term，命中订单关键词：质量约束）\n配煤方案可行性通常指方案是否同时满足订单质量约束、库存约束和业务规则约束。不可行方案不应作为最终推荐方案。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n内蒙古鄂尔多斯不粘煤可用库存：12000.00 吨，库存充足（仓库W002）\n大同弱粘煤可用库存：4200.00 吨，库存正常（仓库W004）\n当前推荐方案涉及煤种库存整体可支撑本次执行，无明显库存不足风险。\n\n请严格输出 JSON，不要输出 Markdown，不要添加多余解释。JSON 必须只包含以下字段：\n{\n  \"ruleBasis\": \"说明命中的规则依据，以及这些规则如何约束当前方案\",\n  \"caseReference\": \"说明可参考的历史案例；如果案例不足，写当前知识库依据不足\",\n  \"recommendReason\": \"说明推荐该方案的原因，结合质量、成本、库存和评分\",\n  \"riskTip\": \"说明质量、库存、成本或执行风险\",\n  \"finalExplanation\": \"面向业务人员的最终综合解释\"\n}\n','{\n  \"ruleBasis\": \"方案命中并遵循以下规则约束：①灰分约束优先校验规则（规则1）要求生成方案后对预测灰分进行校验，若超限则判定不可行或降分。当前方案质量评分100，表明预测灰分未超过订单上限24%。②库存可用性约束规则（规则2）要求各煤种使用量不得超出可用库存。方案中朔州长焰煤600吨（库存10000吨）、鄂尔多斯不粘煤1800吨（库存12000吨）、大同弱粘煤600吨（库存4200吨），均远低于所属煤种库存，库存约束完全满足。③远距离运输质量约束规则（规则3）要求对灰分、硫分严格把关。本方案硫分预测统一为0.6%，远低于订单硫分上限1.2%，在成本与达标风险之间取得较好平衡。④库存稳定性评分规则（规则4）指出单库可用量若低于需求量存在调拨或采购风险。本方案中大同弱粘煤单库4200吨虽高于需求量3000吨，但属于库存正常偏紧状态，已通过稳定性评分87分进行考量。此外，知识库中的发热量下限校验规则要求预测发热量不低于订单目标，方案预测热值5036 kcal/kg > 4500 kcal/kg，满足要求。\",\n  \"caseReference\": \"可参考案例包括：①低硫动力煤组合案例（案例2），该案例通过贫煤+弱粘煤组合严控高硫煤进入配方，与本方案采用的低硫长焰煤、不粘煤、弱粘煤组合思路一致，均以低硫煤种保障硫分达标。②库存紧张下调配比案例（案例1），虽然本方案整体库存充足，但大同弱粘煤库存相对偏紧，案例的“提高周转快煤种占比”策略为未来执行中应对局部库存波动提供了借鉴。③选煤厂智能配煤系统应用案例（知识库历史案例）说明可根据产品质量和储量自动生成配煤方案，与本系统自动生成推荐方案的机制一致，可为业务人员提供背景参考。\",\n  \"recommendReason\": \"推荐方案-A在质量、成本、库存方面表现均衡。质量评分满分100，说明预测灰分、硫分、水分及发热量等关键指标均可靠满足订单要求；发热量预测值5036 kcal/kg超出订单下限，硫分0.6%仅为上限的一半，质量余量充足。成本评分85.23，总成本126.6万元，利用性价比较高的鄂尔多斯不粘煤（占比60%、单价390元/吨）作为主体，搭配高热值大同弱粘煤（520元/吨）和朔州长焰煤（420元/吨），在保证质量的同时控制成本。库存整体充足，无断供风险，方案综合评分达93.15，具备较高的可执行性。\",\n  \"riskTip\": \"大同弱粘煤当前可用库存4200吨，虽能覆盖本次600吨用量，但库存总量仅比需求量多1200吨，如果后续再有较大订单或出库异常，可能面临分仓调拨或临时采购压力，需关注该煤种的动态消耗。另外，方案未明确列出预测灰分和水分数值，虽然系统质量评分满分，建议执行前向系统确认具体预测值，重点核实水分是否接近11%上限，以及灰分是否稳定在24%以内，防范煤质波动。远距离运输场景下，需留意运输过程中的水分变化和落料硫分实测，确保到厂质量与预测一致。\",\n  \"finalExplanation\": \"针对地方工业锅炉用户订单O202604004（需求量3000吨，要求灰分≤24%、硫分≤1.2%、水分≤11%、发热量≥4500 kcal/kg），智能配煤系统推荐方案-A。该方案采用山西朔州长焰煤20%、内蒙古鄂尔多斯不粘煤60%、大同弱粘煤20%的三煤种组合。预测发热量达到5036 kcal/kg，硫分仅0.6%，远优于订单要求，质量评分满分，表明灰分和水分也满足约束。成本方面，利用低单价的鄂尔多斯不粘煤作为基础，搭配高热值煤种，总成本126.6万元折合每吨约422元，性价比突出。库存上，三个煤种可用库存分别为10000吨、12000吨和4200吨，可完全覆盖本次使用量，无明显断供风险。方案综合评分93.15，质量、成本、稳定性均衡优良，建议客户按此方案组织发运。执行中请关注大同弱粘煤库存变化，并做好到厂质量检测，确保实际指标与预测一致。\"\n}','2026-04-24 21:12:07'),
	(6,'blend_generate',107,'低硫 硫分约束 高硫煤限配 高热值 热值补偿 动力煤 低灰 灰分控制 水分控制 高优先级 交付保障 稳定性 配煤方案 质量约束 成本控制 历史案例','低硫,硫分约束,高硫煤限配,高热值,热值补偿,动力煤,低灰,灰分控制,水分控制,高优先级,交付保障,稳定性,配煤方案,质量约束,成本控制,历史案例','17,5,4,9,1,8,3,22,2,11,13,15,19,20,24','deepseek-v4-pro','你是煤矿智能配煤系统中的方案解释助手。\n你的任务是根据订单信息、推荐方案、命中的规则知识、历史案例和 RAG 知识库内容，生成可解释的方案说明。\n\n请严格遵守以下要求：\n1. 只能依据给定的订单、方案和知识库内容进行解释；\n2. 不要编造未提供的煤种、规则、案例或检测数据；\n3. 不要直接修改配煤比例；\n4. 如果知识不足，请在对应字段中说明“当前知识库依据不足”；\n5. 输出内容应面向煤矿业务人员，语言清晰、简洁、专业。\n\n【订单信息】\n订单编号：O202604003\n客户名称：沿海电力集团\n需求量：10000 吨\n灰分要求：≤16%\n硫分要求：≤0.6%\n水分要求：≤8%\n发热量要求：≥5200 kcal/kg\n优先级：3\n交付日期：2026-05-15\n（约束快照）{demandQuantity=10000.00, maxAsh=16.00, maxSulfur=0.60, maxMoisture=8.00, referenceVolatile=25.00, minCalorific=5200.00, priorityLevel=3, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=11}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：4680000.00 元\n质量评分：100\n成本评分：79.43\n稳定性评分：62.69\n综合评分：84.69\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比60.00%，使用量6000吨，预测硫分0.48%，预测热值5318，单价420元/吨\n低灰精选煤：配比20.00%，使用量2000吨，预测硫分0.48%，预测热值5318，单价560元/吨\n大同弱粘煤：配比20.00%，使用量2000吨，预测硫分0.48%，预测热值5318，单价520元/吨\n\n【命中规则】\n规则1：低硫订单优先低硫煤规则（经验规则）；命中原因：因订单目标硫分不高于 0.8%，需执行高硫煤限配策略。——当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。\n规则2：高硫煤限配规则（配比约束）；命中原因：因目标热值不低于 5000 kcal/kg 且硫分要求较严，优先参考低硫煤组合经验。——当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。\n规则3：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨，需关注库存保护规则对可执行性的影响。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则4：发热量下限校验规则（质量约束）；命中原因：因订单目标热值不低于 5000 kcal/kg，建议参考高热值补偿类配煤策略。——配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n规则5：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则6：高热值补偿规则（经验规则）；命中原因：因订单灰分上限低于 18%，需严控高灰煤种作为主配比例。——当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n规则7：低成本煤使用边界规则（配比约束）；命中原因：订单优先级为一般/偏低，可侧重成本可控的配煤路径。——低价煤种可以用于降低方案成本，但若其灰分、硫分或水分偏高，应设置使用边界，避免因低成本导致产品质量不达标。\n规则8：水分控制规则（质量约束）；命中原因：订单水分上限较严，需关注高水分煤种配比与堆放周期。——配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n规则9：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n规则10：分质堆存与分质配煤规则（经验规则）；命中原因：本单需求量大，应校核多仓合计可用量与物流执行能力。——煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。\n\n【参考案例】\n案例1：低硫高热值订单示范案例；匹配原因：低硫场景关键词命中；高热值场景关键词命中；大批量需求关键词命中——需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。 在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。\n案例2：大批量 6000 吨动力煤案例；匹配原因：低硫场景关键词命中；大批量需求关键词命中——大批量订单 6000 吨，硫分不高于 1.2%。 分批发运+多仓组合发运，主配长焰煤与贫煤。\n案例3：库存紧张下调配比案例；匹配原因：高热值场景关键词命中；库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 高热值补偿规则（rule，命中订单关键词：高热值、热值补偿、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n2. 发热量下限校验规则（rule，命中订单关键词：高热值、热值补偿、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n3. 水分控制规则（rule，命中订单关键词：水分控制、配煤方案、质量约束）\n配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n\n\n【历史案例】\n1. 低硫高热值订单示范案例（case，命中订单关键词：低硫、高硫煤限配、高热值）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n2. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n\n\n【术语说明】\n1. 发热量（term，命中订单关键词：动力煤）\n发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。\n2. 硫分（term，命中订单关键词：低硫）\n硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n低灰精选煤可用库存：2200.00 吨，库存偏紧（仓库W007）\n大同弱粘煤可用库存：4200.00 吨，库存正常（仓库W004）\n当前推荐方案涉及煤种中存在单库可用量低于本单总需求量的情况，执行前建议确认调拨或多仓合计。\n\n请严格输出 JSON，不要输出 Markdown，不要添加多余解释。JSON 必须只包含以下字段：\n{\n  \"ruleBasis\": \"说明命中的规则依据，以及这些规则如何约束当前方案\",\n  \"caseReference\": \"说明可参考的历史案例；如果案例不足，写当前知识库依据不足\",\n  \"recommendReason\": \"说明推荐该方案的原因，结合质量、成本、库存和评分\",\n  \"riskTip\": \"说明质量、库存、成本或执行风险\",\n  \"finalExplanation\": \"面向业务人员的最终综合解释\"\n}\n','{\n  \"ruleBasis\": \"本方案主要受低硫订单优先低硫煤规则和高硫煤限配规则约束，因此选用山西朔州长焰煤、低灰精选煤和大同弱粘煤三种低硫煤种，将预测硫分控制在0.48%，满足订单硫分≤0.6%要求。发热量下限校验规则确保预测热值5318 kcal/kg高于订单下限5200 kcal/kg，无需额外高热值补偿。同时水分控制规则要求必须校验预测水分，当前未显示预测水分值，但方案综合评分满分，可推断其预测水分满足≤8%要求，仍建议执行前确认。成本方面，低成本煤使用边界规则允许长焰煤以60%比例作为主配煤种，单价420元/吨，有效控制总成本为468万元。库存可用性约束规则验证各煤种使用量均未超过可用库存，但库存稳定性评分规则指出低灰精选煤单库可用量2200吨低于本单总需求量10000吨，存在供应稳定性风险，需通过调拨或多仓协同解决。灰分约束优先校验规则要求对预测灰分进行校验，方案灰分未显示但应在≤16%以内，否则不可行，当前质量评分100分表明已满足。\"\n  \"caseReference\": \"可参考下列案例：1）低硫高热值订单示范案例，该案例在硫分≤0.80%、发热量≥5000 kcal/kg、灰分≤18%的条件下优先选用低硫煤种，并限制高硫煤，与本方案选煤逻辑一致；2）大批量6000吨动力煤案例，提出分批发运+多仓组合发运模式，适用于本单10000吨大批量交付，建议结合多仓库协同保障供应；3）库存紧张下调配比案例，在库存偏紧时通过下调高库存消耗慢的煤种、提高周转快煤种比例完成交付，可为低灰精选煤库存偏紧情况提供执行参考。\"\n  \"recommendReason\": \"该方案在质量上完全达标，质量评分100分，预测硫分0.48%、热值5318 kcal/kg，推测灰分和水分同样满足订单严格要求；成本方面，总成本468万元，成本评分79.43分，处于合理区间，以低价长焰煤为主配煤种有效控制成本；库存利用上，充分利用库存充足的长焰煤（10000吨），搭配适量偏紧的低灰精选煤和正常的大同弱粘煤，方案可行性强。综合评分84.69分，兼顾质量、成本和稳定性，是当前最优选择。\"\n  \"riskTip\": \"主要风险在于低灰精选煤库存偏紧（可用2200吨，使用2000吨），若生产或调拨延误可能导致供应中断，影响按时交付；且由于单库可用量低于总需求量，存在分仓调拨或多仓协同的执行复杂度，稳定性评分仅62.69分。另外，方案未显示预测水分和灰分具体数值，执行前需补充检测确认，防止水分或灰分超标。成本方面，如果后续需要增加高热值煤补偿或调整比例，可能推高总成本，需警惕。\"\n  \"finalExplanation\": \"针对沿海电力集团的10000吨动力煤订单（灰分≤16%、硫分≤0.6%、水分≤8%、发热量≥5200 kcal/kg），推荐采用“山西朔州长焰煤60%+低灰精选煤20%+大同弱粘煤20%”的配煤方案。该方案预测硫分0.48%、热值5318 kcal/kg，质量完全达标，总成本468万元，性价比优良。方案遵循了低硫优先、高硫煤限配等经验规则，并借鉴了低硫高热值批量订单的成功案例经验。执行时需特别关注低灰精选煤库存仅2200吨，务必提前落实调拨或多仓资源，并建议分批发运以降低供应风险。同时请化验室核准实际灰分和水分数据，确保交付产品与预测一致。本方案综合评分84.69，在满足质量的前提下实现了成本与可执行性的较好平衡。\"\n}','2026-04-24 21:25:44'),
	(7,'blend_generate',111,'低硫 硫分约束 高硫煤限配 高热值 热值补偿 动力煤 低灰 灰分控制 水分控制 配煤方案 质量约束 成本控制 历史案例','低硫,硫分约束,高硫煤限配,高热值,热值补偿,动力煤,低灰,灰分控制,水分控制,配煤方案,质量约束,成本控制,历史案例','17,5,4,9,1,3,22,2,11,13,15,19,20,24','deepseek-v4-flash','你是煤矿智能配煤系统中的方案解释助手。\n你的任务是根据订单信息、推荐方案、命中的规则知识、历史案例和 RAG 知识库内容，生成可解释的方案说明。\n\n请严格遵守以下要求：\n1. 只能依据给定的订单、方案和知识库内容进行解释；\n2. 不要编造未提供的煤种、规则、案例或检测数据；\n3. 不要直接修改配煤比例；\n4. 如果知识不足，请在对应字段中说明“当前知识库依据不足”；\n5. 输出内容应面向煤矿业务人员，语言清晰、简洁、专业。\n\n【订单信息】\n订单编号：O202604005\n客户名称：钢铁企业自备电厂\n需求量：6000 吨\n灰分要求：≤17%\n硫分要求：≤0.7%\n水分要求：≤8.5%\n发热量要求：≥5100 kcal/kg\n优先级：2\n交付日期：2026-05-18\n（约束快照）{demandQuantity=6000.00, maxAsh=17.00, maxSulfur=0.70, maxMoisture=8.50, referenceVolatile=26.00, minCalorific=5100.00, priorityLevel=2, shortlistedCoalCount=5, generatedPlanCount=4, feasiblePlanCount=97}\n\n【推荐方案】\n方案名称：推荐方案-A\n总成本：2616000.00 元\n质量评分：100\n成本评分：88\n稳定性评分：74\n综合评分：89.8\n方案状态：generated\n\n方案明细：\n山西朔州长焰煤：配比80.00%，使用量4800吨，预测硫分0.45%，预测热值5220，单价420元/吨\n河南二1贫煤：配比20.00%，使用量1200吨，预测硫分0.45%，预测热值5220，单价500元/吨\n\n【命中规则】\n规则1：低硫订单优先低硫煤规则（经验规则）；命中原因：因订单目标硫分不高于 0.8%，需执行高硫煤限配策略。——当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。\n规则2：高硫煤限配规则（配比约束）；命中原因：因目标热值不低于 5000 kcal/kg 且硫分要求较严，优先参考低硫煤组合经验。——当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。\n规则3：灰分约束优先校验规则（质量约束）；命中原因：存在煤种可用库存低于 3000 吨，需关注库存保护规则对可执行性的影响。——配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。\n规则4：发热量下限校验规则（质量约束）；命中原因：因订单目标热值不低于 5000 kcal/kg，建议参考高热值补偿类配煤策略。——配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n规则5：库存可用性约束规则（库存约束）；命中原因：候选煤种中存在较高可用库存，可兼顾消化库存的配煤策略。——参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。\n规则6：高热值补偿规则（经验规则）；命中原因：因订单灰分上限低于 18%，需严控高灰煤种作为主配比例。——当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n规则7：水分控制规则（质量约束）；命中原因：订单水分上限较严，需关注高水分煤种配比与堆放周期。——配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n规则8：库存稳定性评分规则（库存约束）；命中原因：部分煤种单库可用量低于本单需求量，存在分仓调拨或增量采购风险。——在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。\n规则9：分质堆存与分质配煤规则（经验规则）；命中原因：本单需求量大，应校核多仓合计可用量与物流执行能力。——煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。\n\n【参考案例】\n案例1：低硫高热值订单示范案例；匹配原因：低硫场景关键词命中；高热值场景关键词命中；大批量需求关键词命中——需求5000吨动力煤，要求硫分不高于0.80%，发热量不低于5000 kcal/kg，灰分不高于18%。 在测试数据中优先选择低硫贫煤、弱粘煤和长焰煤作为候选煤种，并限制高硫煤参与。\n案例2：大批量 6000 吨动力煤案例；匹配原因：低硫场景关键词命中；大批量需求关键词命中——大批量订单 6000 吨，硫分不高于 1.2%。 分批发运+多仓组合发运，主配长焰煤与贫煤。\n案例3：库存紧张下调配比案例；匹配原因：高热值场景关键词命中；库存紧张类案例——需求 4000 吨，热值不低于 4600，库存整体偏紧。 通过下调高库存消耗慢的煤种、提高周转快煤种占比完成交付。\n\n【RAG知识库检索结果】\n【规则知识】\n1. 高热值补偿规则（rule，命中订单关键词：高热值、热值补偿、成本控制）\n当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。\n2. 发热量下限校验规则（rule，命中订单关键词：高热值、热值补偿、配煤方案、质量约束）\n配煤方案的预测发热量应不低于订单目标发热量下限。若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。\n3. 水分控制规则（rule，命中订单关键词：水分控制、配煤方案、质量约束）\n配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。\n\n\n【历史案例】\n1. 低硫高热值订单示范案例（case，命中订单关键词：低硫、高硫煤限配、高热值）\n测试示范案例：订单要求硫分不高于0.80%、发热量不低于5000 kcal/kg、灰分不高于18%。系统应优先检索低硫煤优先规则、高硫煤限配规则和发热量补偿规则。\n2. 选煤厂智能配煤系统应用案例（case，命中订单关键词：配煤方案）\n公开文献介绍，选煤厂智能配煤系统可根据用户要求、产品仓产品质量和储量情况自动给出配煤方案。该案例适合用于说明产品仓质量、库存储量和用户需求共同参与配煤决策。\n\n\n【术语说明】\n1. 发热量（term，命中订单关键词：动力煤）\n发热量表示单位质量煤完全燃烧释放的热量，是动力煤评价和订单约束中的重要指标。配煤方案通常需要满足目标发热量下限。\n2. 硫分（term，命中订单关键词：低硫）\n硫分是煤中硫元素含量指标。硫分偏高会带来环保排放和设备腐蚀等问题，因此低硫订单需要严格控制最终配煤产品硫分。\n\n【库存信息】\n山西朔州长焰煤可用库存：10000.00 吨，库存充足（仓库W001）\n河南二1贫煤可用库存：3600.00 吨，库存正常（仓库W005）\n当前推荐方案涉及煤种中存在单库可用量低于本单总需求量的情况，执行前建议确认调拨或多仓合计。\n\n请严格输出 JSON，不要输出 Markdown，不要添加多余解释。JSON 必须只包含以下字段：\n{\n  \"ruleBasis\": \"说明命中的规则依据，以及这些规则如何约束当前方案\",\n  \"caseReference\": \"说明可参考的历史案例；如果案例不足，写当前知识库依据不足\",\n  \"recommendReason\": \"说明推荐该方案的原因，结合质量、成本、库存和评分\",\n  \"riskTip\": \"说明质量、库存、成本或执行风险\",\n  \"finalExplanation\": \"面向业务人员的最终综合解释\"\n}\n','{\n  \"ruleBasis\": \"本方案命中9条规则，包括低硫订单优先低硫煤规则、高硫煤限配规则、灰分约束优先校验规则、发热量下限校验规则、库存可用性约束规则、高热值补偿规则、水分控制规则、库存稳定性评分规则、分质堆存与分质配煤规则。订单硫分≤0.7%，因此优先选低硫煤（长焰煤硫分0.45%，贫煤硫分0.45%），高硫煤不参与配煤；灰分（方案预测未给出但质量评分100表明通过校验）、发热量（预测5220≥5100）均满足订单；水分控制规则已校验（方案质量评分100）；库存可用性方面，长焰煤库存10000吨、贫煤库存3600吨，方案使用量分别为4800吨和1200吨，均在可用库存范围内；同时高热值补偿规则体现为引入高热值长焰煤（5220）满足热值要求，并控制高价煤种占比（贫煤单价500元/吨，占比20%）。\",\n  \"caseReference\": \"参考案例1（低硫高热值订单示范案例）：硫分≤0.8%、热值≥5000 kcal/kg、灰分≤18%，该案例优先选用低硫贫煤、弱粘煤和长焰煤，与方案中长焰煤+贫煤组合一致；参考案例2（大批量6000吨动力煤案例）：主配长焰煤与贫煤，分批发运+多仓组合发运；参考案例3（库存紧张下调配比案例）：通过提高周转快煤种占比完成交付，本方案中长焰煤库存充足（10000吨）、贫煤库存正常（3600吨），不存在库存紧张问题。\",\n  \"recommendReason\": \"方案综合评分89.8分，其中质量评分100分（全部质量约束达标），成本评分88分（总成本261.6万元，单价加权平均约436元/吨，低于订单预算上限），稳定性评分74分（受贫煤单库可用量低于订单总量影响，但实际使用量仅1200吨，风险可控）。推荐原因：①低硫匹配：两种煤硫分均为0.45%，远低于订单上限0.7%，有力控制硫分风险；②热值充足：预测热值5220 kcal/kg，高于订单最低要求5100；③库存可行性：长焰煤库存充足，贫煤库存可满足1200吨用量；④成本优势：长焰煤单价420元/吨，贫煤500元/吨，方案综合成本较低。\",\n  \"riskTip\": \"①库存风险：河南二1贫煤单库可用量3600吨，虽足够本次1200吨使用，但若订单执行期间需调整比例或后续订单依赖该煤种，需提前确认调拨或多仓合计；②稳定性风险：方案稳定性评分74分偏低，主要因贫煤库存相对有限，建议确认供应链保障能力；③水分风险：订单水分上限8.5%，方案预测水分未明确给出，虽质量评分100但建议实际装车前抽检含水率；④执行风险：订单需求6000吨，方案使用量恰好为6000吨，需确认单批次交付能力及物流安排。\",\n  \"finalExplanation\": \"面向业务人员：推荐方案A采用80%山西朔州长焰煤（4800吨）+20%河南二1贫煤（1200吨），完全满足订单灰分≤17%、硫分≤0.7%、发热量≥5100 kcal/kg、水分≤8.5%的要求。两种煤硫分均低至0.45%，是典型低硫配煤组合；热值5220略高于标准，留有余量。库存方面，长焰煤充足（1万吨），贫煤够用（3600吨），但建议提前与仓库确认贫煤调拨预案，因其单库量小于本单总需求，尽管本次只需1200吨。综合评分89.8分，质量满分，成本合理，是当前最优方案。执行时请关注贫煤水分实测值及长焰煤堆放周期，避免水分超标。\"\n}','2026-04-25 10:46:04'),
	(8,'blend_generate',115,'为订单O2026042501生成低硫高热值配煤方案，并解释为什么推荐该方案。','低硫,高热值,订单O2026042501,配煤方案,库存','26,27,28,31','qwen3:4b-local-demo','订单约束：灰分≤18%，硫分≤0.80%，发热量≥5000；候选批次：PB2026042501-CL、PB2026042502-CL；请结合规则和案例生成解释。','推荐方案P2026042501-A。该方案使用低硫高热值精煤作为主配煤，并搭配洗选降灰精煤，预测指标满足订单要求，且最终质检合格。','2026-04-25 13:28:16'),
	(9,'blend_generate',116,'解释订单O2026042502为什么被标记为严格低硫风险方案。','严格低硫,硫分0.60,风险方案,质量余量','26,29,32','qwen3:4b-local-demo','订单约束：硫分≤0.60%；方案预测硫分约0.598%；最终质检硫分0.610%；请给出风险解释。','该方案理论预测接近硫分上限，质量余量不足。最终质检硫分0.610%超过订单上限，建议增加低硫精煤比例或更换更低硫批次。','2026-04-25 13:28:16'),
	(10,'trace',115,'从最终产品FP2026042501反查它的原煤来源、洗选批次和发运信息。','FP2026042501,批次血缘,原煤,洗选,发运','30,31,28','qwen3:4b-local-demo','请根据batch_lineage说明最终产品FP2026042501的来源路径。','FP2026042501由PB2026042501-CL和PB2026042502-CL混配形成；上游分别来自WP2026042501和WP2026042502；再向上可追溯到RC2026042501、RC2026042502、RC2026042503和RC2026042504；该最终产品已通过SHIP2026042501发运。','2026-04-25 13:28:16'),
	(11,'chat',NULL,'什么是煤矿智能配煤系统中的多阶段煤质数据？','多阶段煤质,geological,raw_coal,wash_feed,clean_coal,final_product','32,31','qwen3:4b-local-demo','请解释煤质数据为什么要按阶段记录。','多阶段煤质用于描述煤在地质、生产、入洗、洗后、混配和最终商品煤阶段的质量变化，能够支撑质量追溯、洗选效果分析和配煤方案解释。','2026-04-25 13:28:16');
