INSERT INTO `rule_knowledge` (`id`, `rule_code`, `rule_name`, `rule_type`, `rule_content`, `applicable_scope`, `priority_level`, `status`, `source_desc`, `create_time`, `update_time`, `business_stage`, `quality_indicator`, `material_type`)
VALUES
	(1,'R001','低硫订单优先低硫煤规则','经验规则','当订单硫分上限较低时，应优先选择硫分较低的煤种参与配煤，并谨慎使用高硫煤。该规则用于降低最终产品硫分超标风险。','低硫订单、环保约束严格订单',5,1,'根据商品煤质量管理要求和智能配煤文献整理','2026-04-18 16:51:19','2026-04-24 20:30:34','blending',NULL,NULL),
	(2,'R002','高硫煤限配规则','配比约束','当订单硫分上限小于等于0.80%时，高硫煤种不宜作为主配煤种，应限制其参与比例或不参与配煤。','target_sulfur <= 0.80 的订单',5,1,'根据商品煤硫分控制要求整理','2026-04-18 16:51:19','2026-04-24 20:30:34','blending',NULL,NULL),
	(3,'R003','灰分约束优先校验规则','质量约束','配煤方案生成后必须对预测灰分进行校验，若预测灰分高于订单灰分上限，则该方案应判定为不可行或降低评分。','全部订单',5,1,'根据煤质指标约束和配煤质量控制要求整理','2026-04-18 16:51:19','2026-04-24 20:30:34','blending',NULL,NULL),
	(4,'R004','发热量下限校验规则','质量约束','配煤方案的预测发热量应不低于订单目标发热量下限；若热值不足，可引入高热值煤种进行补偿，同时评估成本变化。','含目标发热量下限的订单',5,1,'根据动力煤质量评价和配煤优化要求整理','2026-04-18 16:51:19','2026-04-24 20:30:34','blending',NULL,NULL),
	(5,'R005','高热值补偿规则','经验规则','当基础煤种组合无法满足目标发热量时，可优先引入发热量较高且库存可用的煤种进行补偿，但应同步控制高价煤种占比。','热值不足场景',4,1,'根据智能配煤方案生成流程整理','2026-04-18 16:51:19','2026-04-24 20:30:34','blending',NULL,NULL),
	(6,'R006','低成本煤使用边界规则','配比约束','低价煤种可以用于降低方案成本，但若其灰分、硫分或水分偏高，应设置使用边界，避免因低成本导致产品质量不达标。','成本优先订单',4,1,'根据成本与质量多目标权衡思想整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(7,'R007','库存可用性约束规则','库存约束','参与配煤的煤种必须存在可用库存，且方案使用量不得超过该煤种可用库存量。库存不足时应降低该煤种比例或更换候选煤种。','全部订单',5,1,'根据配煤方案可执行性要求整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(8,'R008','库存稳定性评分规则','库存约束','在多个方案质量接近时，应优先选择库存更充足、供应更稳定的方案，以降低执行风险。','候选方案评分排序',3,1,'根据库存稳定性评价要求整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(9,'R009','水分控制规则','质量约束','配煤方案应校验预测水分，若预测水分超过订单水分上限，应降低高水分煤种比例或选择低水分煤种进行替代。','含水分约束订单',4,1,'根据煤的工业分析指标要求整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(10,'R010','挥发分参考规则','质量约束','挥发分可作为煤化程度和燃烧特性的参考指标。对于设置挥发分参考值的订单，方案解释中应说明预测挥发分与目标值的接近程度。','含挥发分参考值订单',3,1,'根据煤质指标解释要求整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(11,'R011','远距离运输质量约束规则','质量约束','对于远距离运输或重点区域供应场景，应更加关注灰分和硫分等质量指标，避免低质煤进入高要求使用场景。','远距离运输、质量要求较高订单',4,1,'根据商品煤质量管理要求整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(12,'R012','分质堆存与分质配煤规则','经验规则','煤炭应尽量按照煤质差异进行分质堆存和分质调用，配煤时优先基于煤质检测结果选择合适煤种组合。','库存管理与配煤调用',3,1,'根据煤质全过程管理和智能配煤实践整理','2026-04-21 08:47:56','2026-04-24 20:30:34','blending',NULL,NULL),
	(13,'R013','相似案例参考规则','经验规则','当存在与当前订单在硫分、灰分、发热量或需求量方面相近的历史案例时，可将其作为方案解释和候选方案生成的参考。','案例检索与方案解释',3,1,'根据案例知识库设计要求整理','2026-04-24 20:30:34','2026-04-24 20:30:34','blending',NULL,NULL),
	(14,'R014','规则与算法协同规则','经验规则','配煤比例不宜完全由大模型直接生成，应由规则筛选、质量计算和评分排序形成候选方案，再由大模型结合知识库生成解释。','大模型辅助配煤场景',5,1,'根据本系统技术路线整理','2026-04-24 20:30:34','2026-04-24 20:30:34','blending',NULL,NULL);
